package dev.recipeeditor.exporters;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

final class ExportFileWriterTest {
    @TempDir Path root;
    private void write(final ExportPlan plan)throws Exception {new ExportFileWriter().write(plan,new ExportControl(),p->{},()->{});}
    @Test void stagesAndWritesEveryFile()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);write(p);for(final var file:p.files().entrySet())assertEquals(file.getValue(),Files.readString(f.target.resolve(file.getKey())));try(final var stream=Files.list(f.target)){assertTrue(stream.noneMatch(path->path.getFileName().toString().startsWith(".recipe-editor-stage-")));}}
    @Test void userFilesAndChangesAfterPreviewAreProtected()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);final var file=f.target.resolve(p.files().keySet().iterator().next());Files.createDirectories(file.getParent());Files.writeString(file,"user");assertThrows(IOException.class,()->write(p));assertEquals("user",Files.readString(file));assertFalse(f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK).valid());}
    @Test void modifiedOwnedFilesAreBackedUp()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);write(p);final var c=f.create("test:new",f.raw.replace("\"count\":2","\"count\":3"));final var ctx=f.context(List.of(c),List.of(),ExportFormat.DATAPACK,Map.of(),List.of(f.manifest(p)),OverwritePolicy.OWNED_UNCHANGED);final var update=f.planner.plan(f.request(ctx));assertTrue(update.valid(),update.diagnostics().toString());write(update);try(final var paths=Files.walk(f.target.resolve(".recipe-editor-backups"))){assertTrue(paths.filter(Files::isRegularFile).anyMatch(path->{try{return Files.readString(path).contains("\"count\":2");}catch(IOException e){return false;}}));}}
    @Test void failureBeforeApplyAndCorruptStagingDoNotTouchOutput()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);final var writer=new ExportFileWriter((i,path)->Files.writeString(path,"corrupt"));assertThrows(IOException.class,()->writer.write(p,new ExportControl(),x->{},()->{}));for(final var path:p.files().keySet())assertFalse(Files.exists(f.target.resolve(path)));}
    @Test void partialFailureRollsBackPreviouslyWrittenFiles()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);final var calls=new java.util.concurrent.atomic.AtomicInteger();final var writer=new ExportFileWriter((i,path)->{if(calls.incrementAndGet()==p.files().size()+2)throw new IOException("simulated second apply failure");});assertThrows(IOException.class,()->writer.write(p,new ExportControl(),x->{},()->{}));for(final var path:p.files().keySet())assertFalse(Files.exists(f.target.resolve(path)));}
    @Test void metadataFailureRestoresOldFilesAndStaleRemovals()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:old",f.raw)),ExportFormat.DATAPACK);write(p);final var c=f.create("test:new",f.raw);final var ctx=f.context(List.of(c),List.of(),ExportFormat.DATAPACK,Map.of(),List.of(f.manifest(p)),OverwritePolicy.OWNED_UNCHANGED);final var update=f.planner.plan(f.request(ctx));assertTrue(update.valid());assertFalse(update.obsoleteFiles().isEmpty());assertThrows(IOException.class,()->new ExportFileWriter().write(update,new ExportControl(),x->{},()->{throw new IOException("manifest write failed");}));for(final var file:p.files().entrySet())assertEquals(file.getValue(),Files.readString(f.target.resolve(file.getKey())));assertFalse(Files.exists(f.target.resolve("datapacks/recipe_editor_testprofile/data/test/recipes/new.json")));}
    @Test void cancellationBeforeApplicationWritesNoRecipeFiles()throws Exception {final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);final var control=new ExportControl();assertTrue(control.cancel());assertThrows(java.util.concurrent.CancellationException.class,()->new ExportFileWriter().write(p,control,x->{},()->{}));for(final var path:p.files().keySet())assertFalse(Files.exists(f.target.resolve(path)));final var applying=new ExportControl();applying.beginApply();assertFalse(applying.cancel());}
    @ParameterizedTest @ValueSource(strings={"../escape.json","C:/escape.json","data/../escape.json","data\\escape.json","/escape.json","data/CON.json","data/escape.json:stream","data/trailing. /a.json"}) void rejectsTraversalAndWindowsSpecialPaths(final String path) {assertThrows(IllegalArgumentException.class,()->ExportPaths.relative(path));}
    @Test void cannotClaimOwnershipOfJarsOrOtherProfiles() {assertThrows(IllegalArgumentException.class,()->ExportPaths.managed("testprofile","mods/test.jar"));assertThrows(IllegalArgumentException.class,()->ExportPaths.managed("testprofile","scripts/recipe_editor_otherprofile_generated.zs"));}
    @Test void sourceDirectoryRequiresSessionConsent()throws Exception {final var f=new ExportFixtures(root);final var ctx=f.context(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);final var profile=new ExportProfile("testprofile","Source",f.source,ExportFormat.DATAPACK,OverwritePolicy.REFUSE,true,"1.20.1","FORGE");final var denied=new ExportContext(ctx.modpack(),ctx.originals(),ctx.savedChanges(),ctx.projectFile(),profile,List.of(),Set.of(),false);assertFalse(f.planner.plan(f.request(denied)).valid());final var allowed=new ExportContext(ctx.modpack(),ctx.originals(),ctx.savedChanges(),ctx.projectFile(),profile,List.of(),Set.of(),true);assertTrue(f.planner.plan(f.request(allowed)).valid());}
    @Test void concurrentEditDuringRollbackRetainsRecoveryDataInsteadOfOverwritingIt()throws Exception {
        final var f=new ExportFixtures(root);final var p=f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK);
        final var sorted=new TreeSet<>(p.files().keySet());final var first=f.target.resolve(sorted.first());final var calls=new java.util.concurrent.atomic.AtomicInteger();
        final var writer=new ExportFileWriter((i,path)->{if(calls.incrementAndGet()==p.files().size()+2){Files.writeString(first,"concurrent user edit");throw new IOException("second file failed");}});
        final var failure=assertThrows(ExportFileWriter.RecoveryRequiredException.class,()->writer.write(p,new ExportControl(),x->{},()->{}));
        assertTrue(failure.getMessage().contains("Recovery journal"));assertEquals("concurrent user edit",Files.readString(first));
        try(final var paths=Files.walk(f.target)){assertTrue(paths.anyMatch(path->path.getFileName().toString().equals("journal.txt")));}
    }
    @Test void symbolicLinkAncestorIsRejectedWhenSupported()throws Exception {final var f=new ExportFixtures(root);final var outside=Files.createDirectories(root.resolve("outside"));try {Files.createSymbolicLink(f.target.resolve("datapacks"),outside);}catch(IOException|UnsupportedOperationException denied){Assumptions.abort("OS does not permit symlink creation");}assertFalse(f.plan(List.of(f.create("test:new",f.raw)),ExportFormat.DATAPACK).valid());}
}
